The button is clicked twice. What does it show?

```jsx
function reducer(state, action) {
  state.count++;
  return state;
}

function Clicker() {
  const [state, dispatch] = useReducer(reducer, { count: 0 });
  return <button onClick={() => dispatch({})}>{state.count}</button>;
}
```

